import{c as a,Q as s,j as p,m as e}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"算子包部署","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子包部署","slug":"算子包部署"},{"level":2,"title":"算子包部署","slug":"算子包部署"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子包部署.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子包部署.md"}'),l={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子包部署.md"};function i(t,n,o,c,d,r){return s(),p("div",null,[...n[0]||(n[0]=[e(`<h1 id="算子包部署" tabindex="-1">算子包部署 <a class="header-anchor" href="#算子包部署" aria-label="Permalink to &quot;算子包部署&quot;">​</a></h1><p>算子包部署指执行自定义算子包的安装，算子工程的编译结果会自动部署到算子包安装目录下。</p><h2 id="算子包部署-1" tabindex="-1">算子包部署 <a class="header-anchor" href="#算子包部署-1" aria-label="Permalink to &quot;算子包部署&quot;">​</a></h2><ol><li><p>自定义算子包安装部署。</p><p>在自定义算子包所在路径下，执行如下命令，安装自定义算子包。</p><p>./custom_opp_&lt;target os&gt;__&lt;target architecture&gt;.run --install-path=&lt;path&gt;</p><p>--install-path为可选参数，用于指定自定义算子包的安装目录。支持指定绝对路径，运行用户需要对指定的安装路径有可读写权限。</p><p>下文描述中的_&lt;vendor_name&gt;_为算子工程编译时CMakePresets.json配置文件中字段“vendor_name”的取值，默认为“customize”。</p><ul><li><p>默认安装场景，不配置--install-path参数，安装成功后会将编译生成的自定义算子相关文件部署到\${INSTALL_DIR}/opp/vendors/_&lt;vendor_name&gt;_目录。\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>自定义算子包默认安装路径\${INSTALL_DIR}/opp/vendors的目录权限与CANN软件包安装用户和安装配置有关。如果因权限不足导致自定义算子包安装失败，可使用--install-path参数并配置环境变量ASCEND_CUSTOM_OPP_PATH来指定安装目录（参考<a href="#li1652971821912">指定目录安装</a>）或者联系CANN软件包的安装用户修改vendors目录权限来解决。详细的案例请参考<a href="./../../../../附录/FAQ/调用算子时出现无法打开config-ini的报错.html">调用算子时出现无法打开config.ini的报错</a>和<a href="./../../../../附录/FAQ/算子包部署时出现权限不足报错.html">算子包部署时出现权限不足报错</a>。</p></div></li><li><p>指定目录安装场景，配置--install-path参数，安装成功后会将编译生成的自定义算子相关文件部署到<code>&lt;path&gt;/vendors/&lt;vendor_name&gt;</code>目录，并在<code>&lt;path&gt;/vendors/&lt;vendor_name&gt;/bin</code>目录下新增set_env.bash，写入当前自定义算子包相关的环境变量。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>如果部署算子包时通过配置--install-path参数指定了算子包的安装目录，则在使用自定义算子前，需要执行<code>source &lt;path&gt;/vendors/&lt;vendor_name&gt;/bin/set_env.bash</code>命令，set_env.bash脚本中将自定义算子包的安装路径追加到环境变量ASCEND_CUSTOM_OPP_PATH中，使自定义算子在当前环境中生效。</li><li>算子包要求架构与执行部署操作的系统架构一致，且部署环境满足算子包的glibc版本依赖，否则会报错，用户可使用--force强制安装。</li></ul></div></li></ul><p>命令执行成功后，自定义算子包中的相关文件将部署至当前环境中。</p></li><li><p>以默认安装场景为例，可查看部署后的目录结构，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>├── opp    //算子库目录</span></span>
<span class="line"><span>│   ├── vendors     //自定义算子所在目录</span></span>
<span class="line"><span>│       ├── config.ini</span></span>
<span class="line"><span>│       └── vendor_name1   // 存储对应厂商部署的自定义算子，此名字为编译自定义算子安装包时配置的vendor_name，若未配置，默认值为customize</span></span>
<span class="line"><span>│           ├── framework     //自定义算子插件库</span></span>
<span class="line"><span>│           ├── op_api</span></span>
<span class="line"><span>│           │   ├── include</span></span>
<span class="line"><span>│           │   │  └── aclnn_xx.h      //算子调用API声明文件</span></span>
<span class="line"><span>│           │   └── lib</span></span>
<span class="line"><span>│           │       └── libcust_opapi.so</span></span>
<span class="line"><span>│           ├── op_impl</span></span>
<span class="line"><span>│           │   └── ai_core</span></span>
<span class="line"><span>│           │       └── tbe</span></span>
<span class="line"><span>│           │           ├── config</span></span>
<span class="line"><span>│           │           ├── vendor_name1_impl    //自定义算子实现代码文件</span></span>
<span class="line"><span>│           │           │   └── dynamic</span></span>
<span class="line"><span>│           │           │       ├── xx.cpp</span></span>
<span class="line"><span>│           │           │       └── xx.py</span></span>
<span class="line"><span>│           │           ├── kernel     //自定义算子二进制文件</span></span>
<span class="line"><span>│           │           │   └── \${soc_version}     //AI处理器类型</span></span>
<span class="line"><span>│           │           │   └── config</span></span>
<span class="line"><span>│           │           └── op_tiling</span></span>
<span class="line"><span>│           │               ├── lib</span></span>
<span class="line"><span>│           │               └── liboptiling.so </span></span>
<span class="line"><span>│           └── op_proto     //自定义算子原型库所在目录</span></span>
<span class="line"><span>│                ├── inc</span></span>
<span class="line"><span>│                │   └── op_proto.h</span></span>
<span class="line"><span>│                └── lib</span></span>
<span class="line"><span>│       ├── vendor_name2   // 存储厂商vendor_name2部署的自定义算子</span></span></code></pre></div></li><li><p>配置自定义算子优先级。</p><p>多算子包共存的情况下，若不同的算子包目录下存在相同OpType的自定义算子，则以优先级高的算子包目录下的算子为准。下面介绍如何配置算子包优先级：</p><ul><li><p>默认安装场景</p><p>当“opp/vendors”目录下存在多个厂商的自定义算子时，您可通过配置“opp/vendors”目录下的“config.ini”文件，配置自定义算子包的优先级。</p><p>“config.ini”文件的配置示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>load_priority=vendor_name1,vendor_name2,vendor_name3</span></span></code></pre></div><ul><li>“load_priority”：优先级配置序列的关键字，不允许修改。</li><li>“vendor_name1,vendor_name2,vendor_name3”：自定义算子厂商的优先级序列，按照优先级从高到低的顺序进行排列。</li></ul></li><li><p>指定目录安装场景</p><p>指定目录安装场景下，如果需要多个自定义算子包同时生效，分别执行各算子包安装路径下的set_env.bash脚本即可。每次脚本执行都会将当前算子包的安装路径追加到ASCEND_CUSTOM_OPP_PATH环境变量的最前面。因此可以按照脚本执行顺序确定优先级：脚本执行顺序越靠后，算子包优先级越高。</p><p>比如先执行<code>source &lt;path&gt;/vendor_name1/bin/set_env.bash</code>，后执行<code>source &lt;path&gt;/vendor_name2/bin/set_env.bash</code>，vendor_name2算子包的优先级高于vendor_name1。ASCEND_CUSTOM_OPP_PATH示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ASCEND_CUSTOM_OPP_PATH=&lt;path&gt;/vendor_name2:&lt;path&gt;/vendor_name1:</span></span></code></pre></div></li><li><p>指定目录安装场景下安装的算子包优先级高于默认方式安装的算子包。</p></li></ul></li></ol>`,4)])])}const v=a(l,[["render",i]]);export{h as __pageData,v as default};
